SELECT packet_id as dictValue, packet_wx_name as dictLabel, package_id, wechat_pay, balance_pay, packet_valid_type, packet_cost, in_stock, packet_flow, packet_valid_name, packet_valid_time, packet_price, is_month FROM yz_agent_packet
dept_id in
#{agent_id}

SELECT iccid, true_flow, (IF(use_so_flow>0,use_so_flow,0)+IF(use_flow>0,use_flow,0)) AS use_so_flow_sum, ROUND(((IF(use_so_flow>0,use_so_flow,0)+IF(use_flow>0,use_flow,0)) / true_flow) * 100,2) as Percentage, (true_flow - (IF(use_so_flow>0,use_so_flow,0)+IF(use_flow>0,use_flow,0))) as surplus, b.packet_name, b.packet_valid_time, b.packet_valid_name FROM ( SELECT * FROM yz_card_flow WHERE iccid IN
#{iccid_arrs}
ORDER BY start_time DESC LIMIT 99999999 ) a , yz_card_packet b WHERE a.packet_id = b.packet_id and a.package_id = b.package_id GROUP BY a.iccid

mapper.update:
update yz_card_flow

	use_true_flow = #{use_true_flow},
	use_so_flow = #{use_so_flow},

		status = #{status}



	id =#{id}

mapper.select:
select
	COUNT(iccid)
from
	yz_card_flow

	iccid =#{iccid}
	and ord_no =#{ord_no}

SELECT DATE_FORMAT( A.end_time, "%Y-%m-%d %H:%i:%S" ) AS ymd FROM yz_card_flow A, yz_card_packet B
A.iccid = #{iccid} AND A.package_id = B.package_id AND A.packet_id = B.packet_id AND B.packet_type = 0 AND A.STATUS = 1
ORDER BY A.end_time DESC LIMIT 1;

SELECT
	packet_flow,
	packet_valid_time,
	packet_valid_name,
	is_month
FROM
	yz_agent_packet

	package_id = #{package_id}
	and packet_id = #{packet_id}
	and dept_id  = #{agent_id}

select packet_type FROM yz_card_packet
package_id =#{package_id} and packet_id =#{packet_id}
LIMIT 1

SELECT id, package_id, packet_id, ord_no, true_flow, error_flow, DATE_FORMAT( start_time, "%Y-%m-%d %H:%i:%S" ) AS start_time, DATE_FORMAT( end_time, "%Y-%m-%d %H:%i:%S" ) AS end_time, DATE_FORMAT( create_time, "%Y-%m-%d %H:%i:%S" ) AS create_time, ord_type, status, packet_type, use_flow, iccid, error_time, validate_type, DATE_FORMAT( validate_time, "%Y-%m-%d %H:%i:%S" ) AS validate_time, use_true_flow, use_so_flow FROM yz_card_flow
ord_no IN
#{ordNoID}

SELECT t1.msisdn, t1.iccid, t1.imsi, t1.imei, t1.activate_date, t1.due_expire_time, t2.dept_name, t1.remarks, t5.true_flow, t5.use_so_flow_sum, t1.used, t1.remaining, t1.status_ShowId, t1.customize_grouping, t5.packet_name, t1.network_type, t4.cd_alias, t4.cd_operator_type FROM yz_card_info t1 LEFT JOIN sys_dept t2 ON t1.dept_id = t2.dept_id LEFT JOIN yz_card_packet t3 ON t1.package_id = t3.package_id LEFT JOIN yz_card_route t4 ON t1.channel_id = t4.cd_id LEFT JOIN (SELECT iccid, b.packet_name, true_flow, (IF(use_so_flow>0,use_so_flow,0)+IF(use_flow>0,use_flow,0)) AS use_so_flow_sum FROM ( SELECT * FROM yz_card_flow WHERE iccid IN
#{card.iccid}
ORDER BY create_time DESC) a left join yz_card_packet b ON a.packet_id = b.packet_id GROUP BY a.iccid ) AS t5 ON t1.iccid = t5.iccid
t2.`status` = 0
AND t1.iccid = #{value} OR t1.imsi = #{value} OR t1.msisdn = #{value}
and
t1.vid
t1.msisdn
t1.iccid
t1.imsi
IN
#{UpArr.cardNumber}
and t1.vid in
#{batch_query_arr}
and t1.msisdn in
#{batch_query_arr}
and t1.iccid in
#{batch_query_arr}
and t1.imsi in
#{batch_query_arr}
and t1.imei in
#{batch_query_arr}
and
t1.vid
t1.msisdn
t1.iccid
t1.imsi
t1.imei
BETWEEN #{StartValue} AND #{EndValue}
GROUP BY t1.iccid
